from produire import produire,paras,table,steps
parts=[
('Le trouble temporo-mandibulaire douloureux concerne articulation et muscles de la mastication. Les {composantes possibles} expliquent une douleur ressentie près de l’oreille malgré une otoscopie normale.',paras('Les troubles articulaires et musculaires peuvent s’associer. Un bruit articulaire isolé sans douleur ni limitation ne suffit pas à expliquer toute plainte auriculaire.')),
('Ce diagnostic fait partie des causes importantes d’otalgie projetée. Les {facteurs associés} doivent être recherchés sans leur attribuer automatiquement toute la douleur.',paras('Serrement des dents, habitudes de mastication, stress et dysfonction articulaire peuvent contribuer. L’existence d’une gouttière ou d’un bruxisme connu n’exclut pas une nouvelle cause dentaire ou ORL.')),
('Douleur musculaire, dérangement discal ou atteinte articulaire peuvent gêner la fonction. Les {mécanismes de projection} expliquent l’irradiation à l’oreille et à la tempe.',paras('Les mouvements mandibulaires sollicitent articulation, disque et muscles. La reproduction de la douleur habituelle par ces structures renforce l’hypothèse, sans rendre inutiles les recherches de signes d’alarme.')),
('Il faut distinguer trouble mécanique et situation urgente. Les {signes d’alarme} imposent une autre filière.',paras('Fièvre, gonflement, trismus récent important, impossibilité de boire, traumatisme ou mâchoire bloquée en ouverture demandent une évaluation rapide. Céphalée temporale nouvelle, douleur de mâchoire à l’effort et trouble visuel font rechercher une artérite à cellules géantes en urgence.')),
('L’entretien relie douleur et fonction mandibulaire. Les {questions ciblées} précisent limitation, blocage et habitudes.',paras('Demander douleur à la mastication, au bâillement, au réveil, serrement diurne, bruits et épisodes de blocage. Rechercher soins dentaires récents, traumatisme, symptômes articulaires ailleurs, gêne à la déglutition ou masse cervicale.')),
('Examiner ouverture, trajectoire et douleur provoquée. Les {gestes utiles} incluent palpation de l’articulation et des muscles masticateurs.',paras('Comparer les côtés et rechercher si la douleur habituelle est reproduite, sans manœuvre forcée. Examiner aussi dents, bouche, cou et oreilles ; une seule palpation douloureuse ne constitue pas un bilan complet.')),
('Le {diagnostic différentiel} comprend plusieurs causes de douleur faciale et auriculaire. Une otoscopie normale ne désigne pas automatiquement l’articulation.',table(['Indice','À rechercher'],[['Dent sensible à la mastication ou tuméfaction gingivale.','Cause odontogène.'],['Gêne pharyngée, masse ou amaigrissement.','Lésion ORL, notamment tumorale.'],['Céphalée temporale avec symptômes visuels.','Artérite à cellules géantes.'],['Blocage après ouverture forcée.','Luxation ou autre atteinte mécanique.'],['Fièvre et trismus progressif.','Infection profonde ou articulaire.']])) ,
('Le diagnostic est principalement clinique et fonctionnel. Les {arguments positifs} associent douleur habituelle et sollicitations de l’appareil manducateur.',paras('Douleur modulée par les mouvements et reproduite à l’examen soutient une origine musculaire ou articulaire. Un claquement isolé ne justifie pas à lui seul une procédure irréversible.')),
('L’imagerie n’est pas nécessaire pour chaque présentation simple. Les {indications ciblées} concernent formes atypiques ou persistantes.',paras('Scanner ou IRM sont choisis selon la question osseuse, discale ou autre par le spécialiste. Une suspicion d’infection, de tumeur, d’arthrite inflammatoire ou un traumatisme modifie le bilan.')),
('La {stratégie progressive} privilégie des mesures conservatrices. Le suivi vérifie fonction et retentissement.',steps('Écarter les urgences et les autres causes de douleur projetée.', 'Identifier les gestes aggravants et proposer information, adaptation des sollicitations et antalgie adaptée.', 'Organiser évaluation dentaire et physiothérapie spécialisée si nécessaire ; discuter une gouttière selon indication.', 'Réévaluer persistance, blocage ou diagnostic atypique avant d’envisager une procédure spécialisée.')),
('Les soins conservateurs constituent généralement le premier niveau. Les {options adaptées} visent à diminuer douleur et contraintes sans immobilisation prolongée injustifiée.',paras('Pendant une poussée, privilégier une alimentation temporairement plus facile à mâcher, éviter gomme et ouverture excessive, et adapter chaud ou froid protégé selon confort. Relâchement musculaire et physiothérapie spécialisée peuvent être utiles.', 'Une gouttière est choisie et surveillée par le dentiste selon le cas. Lavage articulaire ou chirurgie concernent des indications sélectionnées ; ne pas promettre une disparition de douleur ni proposer une correction occlusale irréversible à partir de la seule otalgie.')),
('La {prévention des rechutes} repose sur l’identification des sollicitations et un suivi adapté. Une douleur chronique peut nécessiter une approche multidisciplinaire.',paras('Repérer le serrement des dents, limiter les habitudes aggravantes et maintenir une activité mandibulaire adaptée. Réexaminer toute nouvelle tuméfaction, douleur dentaire, gêne pharyngée ou modification du profil.')),
('Une douleur reproduite par la mâchoire soutient une origine temporo-mandibulaire. L’oreille normale n’exclut pas une autre maladie importante. Les mesures conservatrices précèdent habituellement les gestes invasifs. Un bruit isolé ne dicte pas le traitement.','')]
quiz=[('Le trouble concerne-t-il seulement l’articulation ?','Non : les muscles masticateurs peuvent participer.'),('Une otoscopie normale prouve-t-elle ce diagnostic ?','Non.'),('Quel lien fonctionnel est utile ?','Douleur modulée ou reproduite par mastication et mouvement mandibulaire.'),('Un claquement indolore impose-t-il une chirurgie ?','Non.'),('Faut-il examiner les dents ?','Oui.'),('Fièvre et trismus récent sont-ils à banaliser ?','Non : rechercher une infection ou une autre urgence.'),('Que suggèrent céphalée temporale et trouble visuel ?','Une possible artérite à cellules géantes, à évaluer en urgence.'),('Le scanner est-il systématique ?','Non.'),('Quel est généralement le premier niveau de traitement ?','Mesures conservatrices, information et adaptation des sollicitations.'),('La gomme à mâcher aide-t-elle pendant une poussée ?','Elle peut aggraver les sollicitations ; mieux vaut l’éviter temporairement.'),('Une gouttière doit-elle être adaptée par un professionnel ?','Oui.'),('La physiothérapie spécialisée peut-elle aider ?','Oui selon le tableau.'),('Une douleur persistante garantit-elle une indication chirurgicale ?','Non : revoir diagnostic et stratégie.'),('Une nouvelle masse cervicale doit-elle être attribuée au bruxisme ?','Non : elle nécessite un bilan distinct.')]
produire(8,parts,quiz,(5,7,11,13,23))
